:root {
  --bg: #02030a;
  --panel: rgba(8, 13, 29, 0.78);
  --panel-solid: #080d1d;
  --line: rgba(154, 207, 255, 0.14);
  --line-bright: rgba(154, 225, 255, 0.34);
  --ink: #eef8ff;
  --muted: #8296b6;
  --dim: #52637f;
  --cyan: #2ee6ff;
  --cyan-2: #00a9ff;
  --pink: #ff3cac;
  --green: #42f5a7;
  --gold: #ffd166;
  --red: #ff4d67;
  --font-display: 'Orbitron', 'Arial Black', sans-serif;
  --font-body: 'Rajdhani', 'Trebuchet MS', sans-serif;
  --glass-blur: blur(18px);
  --ease: cubic-bezier(.2, .8, .2, 1);
}

* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; width: 100%; height: 100%; overflow: hidden; }
body {
  background: var(--bg);
  color: var(--ink);
  font-family: var(--font-body);
  font-weight: 500;
  -webkit-font-smoothing: antialiased;
  user-select: none;
  -webkit-user-select: none;
}
button, input, select { font: inherit; color: inherit; }
button { border: 0; background: none; cursor: pointer; }
h1, h2, h3, p { margin: 0; }
em { font-style: normal; }
.hidden { display: none !important; }

#gameCanvas {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  z-index: 0;
  touch-action: none;
}

.screen-fx {
  position: fixed; inset: 0; z-index: 1; pointer-events: none;
  background:
    radial-gradient(ellipse at 50% 45%, transparent 30%, rgba(0, 0, 10, 0.30) 72%, rgba(0, 0, 8, 0.83) 100%),
    linear-gradient(90deg, rgba(1, 3, 12, 0.80) 0%, rgba(1, 3, 12, 0.18) 44%, transparent 68%),
    linear-gradient(0deg, rgba(2, 4, 14, 0.75) 0%, transparent 25%, transparent 78%, rgba(2, 4, 14, 0.5) 100%);
  transition: opacity .5s ease;
}
body.in-game .screen-fx {
  background:
    radial-gradient(ellipse at 50% 50%, transparent 45%, rgba(0, 0, 10, 0.2) 80%, rgba(0, 0, 8, 0.72) 100%),
    linear-gradient(0deg, rgba(2, 4, 14, 0.32) 0%, transparent 22%, transparent 84%, rgba(2, 4, 14, 0.28) 100%);
}
body.in-editor .screen-fx {
  background: radial-gradient(ellipse at 50% 45%, transparent 35%, rgba(0, 0, 10, 0.15) 78%, rgba(0, 0, 8, 0.45) 100%);
}
.scanlines {
  position: fixed; inset: 0; z-index: 2; pointer-events: none; opacity: .22;
  background: repeating-linear-gradient(0deg, transparent 0 3px, rgba(150, 220, 255, .035) 3px 4px);
  mix-blend-mode: overlay;
}

/* ============================== SHARED ============================== */
.screen { position: fixed; inset: 0; z-index: 10; display: none; }
.screen.active { display: flex; }
.micro { font-family: var(--font-display); font-size: 9px; letter-spacing: .22em; color: var(--muted); font-weight: 500; }
.kicker { display: block; font-family: var(--font-display); font-size: 10px; letter-spacing: .32em; color: var(--cyan); font-weight: 500; }
.key {
  display: inline-flex; align-items: center; justify-content: center;
  min-width: 26px; height: 23px; padding: 0 7px; margin-right: 5px;
  border: 1px solid rgba(180, 225, 255, .26); border-bottom-color: rgba(180, 225, 255, .14);
  border-radius: 5px; background: rgba(150, 210, 255, .07);
  font-family: var(--font-display); font-size: 8px; letter-spacing: .06em; color: #d7ecff;
  box-shadow: inset 0 1px 0 rgba(255,255,255,.08);
}
.dot-green { display: inline-block; width: 6px; height: 6px; border-radius: 50%; background: var(--green); box-shadow: 0 0 10px var(--green); margin-right: 7px; }
.live-dot { display: inline-block; width: 7px; height: 7px; border-radius: 50%; background: var(--green); box-shadow: 0 0 0 4px rgba(66, 245, 167, .1), 0 0 12px var(--green); animation: livePulse 2s infinite; }
.live-dot.small { width: 5px; height: 5px; }
@keyframes livePulse { 0%, 100% { opacity: 1; } 50% { opacity: .35; } }

.btn {
  position: relative; display: inline-flex; align-items: center; justify-content: center; gap: 12px;
  min-height: 48px; padding: 0 23px; border-radius: 8px;
  font-family: var(--font-display); font-size: 10px; letter-spacing: .14em; font-weight: 500;
  border: 1px solid var(--line-bright); color: var(--ink);
  background: rgba(12, 22, 44, .55);
  transition: transform .18s var(--ease), border-color .18s, background .18s, box-shadow .18s;
  overflow: hidden;
}
.btn::after {
  content: ''; position: absolute; inset: 0; background: linear-gradient(110deg, transparent 20%, rgba(255,255,255,.14) 45%, transparent 60%);
  transform: translateX(-120%); transition: transform .5s var(--ease); pointer-events: none;
}
.btn:hover::after { transform: translateX(120%); }
.btn:hover { transform: translateY(-2px); border-color: rgba(180, 238, 255, .65); background: rgba(20, 40, 70, .65); }
.btn:active { transform: translateY(0); }
.btn-primary {
  color: #021018; border-color: transparent;
  background: linear-gradient(110deg, #74f6ff, #20c7ff 52%, #178fff);
  box-shadow: 0 8px 38px rgba(0, 196, 255, .25), inset 0 1px 0 rgba(255,255,255,.55);
  font-weight: 900;
}
.btn-primary:hover { background: linear-gradient(110deg, #a2faff, #38d5ff 52%, #289dff); box-shadow: 0 12px 48px rgba(0, 210, 255, .38); }
.btn-ghost { background: rgba(8, 18, 36, .48); }
.btn-quiet { color: var(--muted); border-color: var(--line); background: transparent; }
.btn-quiet:hover { color: var(--ink); }
.btn-tiny { min-height: 34px; padding: 0 13px; font-size: 8px; letter-spacing: .11em; border-radius: 6px; }
.btn.wide { width: 100%; }

.icon-btn {
  width: 38px; height: 38px; border-radius: 8px; border: 1px solid var(--line);
  color: var(--muted); font-family: var(--font-display); font-size: 11px;
  display: grid; place-items: center; transition: .2s;
}
.icon-btn:hover { color: var(--ink); border-color: var(--line-bright); background: rgba(100, 200, 255, .08); }
.sound-off { display: none; }
body.muted .sound-on { display: none; }
body.muted .sound-off { display: inline; }

/* ============================== NAV / MENU ============================== */
.nav {
  position: absolute; top: 0; left: 0; right: 0; height: 86px;
  display: flex; align-items: center; gap: 34px; padding: 0 4.2vw;
  z-index: 15;
}
.brand { display: flex; align-items: center; gap: 12px; color: var(--ink); }
.brand-mark {
  width: 36px; height: 36px; position: relative; display: block;
  border: 2px solid var(--cyan); border-radius: 4px;
  transform: rotate(45deg); box-shadow: 0 0 20px rgba(46,230,255,.28), inset 0 0 12px rgba(46,230,255,.15);
  background: rgba(20, 130, 170, .12);
}
.brand-mark i { position: absolute; inset: 8px; background: var(--cyan); box-shadow: 0 0 14px var(--cyan); }
.brand-text { font-family: var(--font-display); font-size: 11px; letter-spacing: .19em; font-weight: 500; }
.brand-text b { color: var(--cyan); font-weight: 900; }
.brand-text em { font-size: 8px; padding: 3px 5px; border: 1px solid var(--line-bright); border-radius: 3px; color: var(--pink); margin-left: 2px; letter-spacing: .05em; }
.nav-links { display: flex; align-items: center; gap: 27px; margin-left: 20px; }
.nav-link {
  font-family: var(--font-display); font-size: 9px; letter-spacing: .2em; color: #7d92b0;
  padding: 8px 0; position: relative; transition: color .2s;
}
.nav-link::after { content: ''; position: absolute; left: 0; right: 100%; bottom: 0; height: 1px; background: var(--cyan); box-shadow: 0 0 8px var(--cyan); transition: right .25s var(--ease); }
.nav-link:hover, .nav-link.active { color: var(--ink); }
.nav-link:hover::after, .nav-link.active::after { right: 0; }
.nav-actions { margin-left: auto; display: flex; align-items: center; gap: 15px; }
.free-pill {
  display: flex; align-items: center; gap: 8px; padding: 7px 11px 6px;
  border: 1px solid rgba(66,245,167,.27); border-radius: 100px;
  color: #9affd1; font-family: var(--font-display); font-size: 7px; letter-spacing: .18em;
  background: rgba(30, 120, 85, .08);
}
.free-pill i { display: block; width: 5px; height: 5px; background: var(--green); border-radius: 50%; box-shadow: 0 0 8px var(--green); }

.menu-main {
  position: relative; z-index: 10; width: 100%; height: 100%;
  display: grid; grid-template-columns: minmax(0, 1.16fr) minmax(300px, .84fr);
  align-items: center; padding: 96px 5.2vw 84px;
}
.hero-copy { max-width: 810px; padding-top: 10px; }
.eyebrow {
  display: flex; align-items: center; gap: 11px; margin-bottom: 18px;
  font-family: var(--font-display); font-size: 8.5px; letter-spacing: .22em; color: #b8d3eb;
  animation: fadeUp .8s .1s both;
}
.eyebrow-sep { color: var(--dim); }
.hero-title { position: relative; line-height: .8; animation: fadeUp .9s .18s both; }
.title-top {
  display: block; margin-left: 5px; font-family: var(--font-display); font-weight: 500;
  font-size: clamp(19px, 2.2vw, 31px); letter-spacing: .56em; color: #9ab7d2;
  text-shadow: 0 0 28px rgba(120, 215, 255, .3);
}
.title-main {
  display: block; margin-left: -5px; font-family: var(--font-display); font-weight: 900;
  font-size: clamp(76px, 10.6vw, 166px); letter-spacing: -.045em;
  background: linear-gradient(178deg, #ffffff 2%, #c9f8ff 30%, #43d8ff 62%, #0b77c7 92%);
  -webkit-background-clip: text; background-clip: text; color: transparent;
  filter: drop-shadow(0 8px 34px rgba(0, 180, 255, .27)) drop-shadow(0 0 2px rgba(180, 250, 255, .5));
  white-space: nowrap;
}
.title-badge {
  display: inline-flex; align-items: center; justify-content: center; vertical-align: top;
  margin-left: 9px; margin-top: .6em; width: 1.5em; height: .72em;
  font-family: var(--font-display); font-size: .17em; font-weight: 900; letter-spacing: .02em;
  color: #03101a; background: linear-gradient(120deg, #ff9bd2, #ff3cac);
  border-radius: 4px; transform: rotate(7deg); box-shadow: 0 0 24px rgba(255,60,172,.4);
  -webkit-text-fill-color: #03101a;
}
.hero-sub {
  margin-top: 24px; max-width: 510px;
  font-size: 19px; line-height: 1.35; font-weight: 500; color: #b9cbe0; letter-spacing: .02em;
  animation: fadeUp .9s .28s both;
}
.hero-cta { display: flex; gap: 13px; margin-top: 30px; animation: fadeUp .9s .36s both; }
.btn-play { min-width: 225px; justify-content: flex-start; padding: 10px 22px; min-height: 60px; }
.btn-play-icon { font-size: 13px; width: 31px; height: 31px; display: grid; place-items: center; border-radius: 50%; background: rgba(0, 25, 40, .18); }
.btn-stack { display: flex; flex-direction: column; align-items: flex-start; gap: 4px; }
.btn-stack b { font-size: 10px; letter-spacing: .14em; }
.btn-stack small { font-family: var(--font-display); font-size: 6.5px; font-weight: 500; letter-spacing: .14em; opacity: .62; }
.btn-ghost { min-height: 60px; padding: 10px 20px; justify-content: flex-start; }
.btn-ico { font-size: 17px; color: var(--cyan); }
.hero-cta .btn-ghost .btn-stack b { font-size: 9px; }
.feature-row {
  display: flex; gap: 26px; margin-top: 33px; padding-top: 18px; border-top: 1px solid rgba(140, 200, 255, .12);
  font-family: var(--font-display); font-size: 7.5px; letter-spacing: .13em; color: #7089a7;
  animation: fadeUp .9s .44s both;
}
.feature-row b { color: #dff8ff; font-size: 11px; margin-right: 4px; }

.hero-side { justify-self: end; align-self: end; display: flex; flex-direction: column; gap: 10px; margin-bottom: 6px; animation: fadeUp 1s .5s both; }
.side-card {
  border: 1px solid rgba(150, 215, 255, .16); background: rgba(5, 12, 27, .62);
  backdrop-filter: var(--glass-blur); -webkit-backdrop-filter: var(--glass-blur);
  border-radius: 10px; box-shadow: 0 24px 60px rgba(0,0,0,.35);
}
.now-card { width: 284px; padding: 14px; }
.side-card-label { font-family: var(--font-display); font-size: 7px; letter-spacing: .19em; color: #9bb5cf; display: flex; align-items: center; gap: 8px; }
.now-art {
  position: relative; height: 94px; margin: 12px 0 12px; border-radius: 6px; overflow: hidden;
  background: radial-gradient(circle at 54% 50%, rgba(46,230,255,.26), transparent 46%), linear-gradient(120deg, #061a3d, #073968 62%, #071329);
  border: 1px solid rgba(100, 220, 255, .17);
}
.now-art::before { content: ''; position: absolute; inset: 0; background-image: linear-gradient(rgba(64,220,255,.13) 1px, transparent 1px), linear-gradient(90deg, rgba(64,220,255,.13) 1px, transparent 1px); background-size: 16px 16px; opacity: .5; transform: perspective(130px) rotateX(54deg) scale(1.45) translateY(17px); }
.now-num { position: absolute; top: 8px; left: 10px; font-family: var(--font-display); font-size: 8px; color: #89a9c5; letter-spacing: .1em; }
.now-glyph { position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); font-size: 34px; color: var(--cyan); text-shadow: 0 0 22px var(--cyan); animation: slowSpin 12s linear infinite; }
.now-ring { position: absolute; top: 50%; left: 50%; width: 60px; height: 60px; transform: translate(-50%,-50%) rotate(25deg); border: 1px solid rgba(120, 250, 255, .55); border-radius: 50%; box-shadow: 0 0 16px rgba(46,230,255,.22); }
.now-info h3 { font-family: var(--font-display); font-size: 9px; letter-spacing: .13em; text-transform: uppercase; font-weight: 500; }
.now-meta { display: flex; gap: 7px; margin-top: 6px; font-family: var(--font-display); font-size: 6.5px; letter-spacing: .1em; color: #829db9; }
.now-meta span { padding: 3px 5px; background: rgba(120, 190, 255, .08); border-radius: 2px; }
.mini-bar { height: 3px; background: rgba(120, 190, 255, .12); margin-top: 9px; overflow: hidden; }
.mini-bar i { display: block; height: 100%; background: var(--cyan); box-shadow: 0 0 10px var(--cyan); }
.stat-strip { width: 284px; display: flex; justify-content: space-between; padding: 13px 16px; }
.stat-strip div { display: flex; flex-direction: column; gap: 2px; }
.stat-strip b { font-family: var(--font-display); font-size: 12px; color: #dff8ff; }
.stat-strip span { font-family: var(--font-display); font-size: 6px; letter-spacing: .14em; color: #7892b0; }

.menu-foot {
  position: absolute; bottom: 0; left: 0; right: 0; height: 54px; z-index: 10;
  display: flex; align-items: center; justify-content: space-between; padding: 0 4.2vw;
  border-top: 1px solid rgba(140, 200, 255, .11);
  font-family: var(--font-display); font-size: 7px; letter-spacing: .14em; color: #647c99;
}
.controls-hint { display: flex; align-items: center; gap: 6px; }
.controls-hint .key { height: 20px; min-width: 22px; margin: 0 1px 0 8px; }
.foot-note span { color: var(--cyan); margin: 0 6px; }
@keyframes slowSpin { to { transform: translate(-50%,-50%) rotate(360deg); } }
@keyframes fadeUp { from { opacity: 0; transform: translateY(24px); } to { opacity: 1; transform: translateY(0); } }

/* ============================== PANEL SCREENS ============================== */
.panel-screen {
  flex-direction: column; overflow: hidden;
  background:
    radial-gradient(ellipse at 18% 20%, rgba(20, 76, 120, .17), transparent 48%),
    linear-gradient(105deg, rgba(2, 5, 14, .98) 0%, rgba(3, 8, 20, .93) 46%, rgba(3, 8, 20, .79) 100%);
  backdrop-filter: blur(7px); -webkit-backdrop-filter: blur(7px);
}
.subnav {
  flex: 0 0 84px; display: flex; align-items: center; gap: 28px; padding: 0 3.6vw;
  border-bottom: 1px solid rgba(150, 210, 255, .12);
  background: linear-gradient(180deg, rgba(4,10,24,.82), rgba(4,10,24,.35));
  z-index: 3;
}
.back-btn {
  display: flex; align-items: center; gap: 9px; color: #9db3cc;
  font-family: var(--font-display); font-size: 8px; letter-spacing: .19em; transition: color .2s; white-space: nowrap;
}
.back-btn span { font-size: 15px; color: var(--cyan); }
.back-btn:hover { color: #fff; }
.subnav-title { display: flex; flex-direction: column; gap: 4px; }
.subnav-title h2 { font-family: var(--font-display); font-size: 15px; letter-spacing: .14em; font-weight: 900; }
.subnav-stats { margin-left: auto; display: flex; align-items: center; gap: 20px; font-family: var(--font-display); font-size: 7px; letter-spacing: .14em; color: #9db3cc; }
.levels-body { flex: 1; overflow-y: auto; padding: 28px 3.6vw 50px; scrollbar-width: thin; scrollbar-color: rgba(46,230,255,.3) rgba(255,255,255,.04); }
.levels-body::-webkit-scrollbar { width: 7px; }
.levels-body::-webkit-scrollbar-thumb { background: rgba(46,230,255,.25); border-radius: 10px; }
.levels-intro { display: flex; align-items: flex-end; gap: 38px; margin-bottom: 27px; }
.levels-intro h1 { font-family: var(--font-display); font-size: clamp(26px, 3.2vw, 44px); line-height: 1.04; letter-spacing: -.02em; font-weight: 900; margin-top: 9px; }
.levels-intro h1 em { color: var(--cyan); font-style: normal; }
.levels-desc { max-width: 440px; color: #9db0c7; font-size: 15px; line-height: 1.35; margin-bottom: 5px; }
.progress-orb {
  margin-left: auto; flex: 0 0 auto; width: 108px; height: 108px; border-radius: 50%;
  border: 1px solid rgba(46,230,255,.3); background: radial-gradient(circle, rgba(46,230,255,.12), transparent 65%);
  display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 2px;
  box-shadow: inset 0 0 22px rgba(46,230,255,.08), 0 0 34px rgba(46,230,255,.07);
}
.progress-orb span { font-family: var(--font-display); font-size: 22px; font-weight: 900; color: var(--cyan); text-shadow: 0 0 20px rgba(46,230,255,.5); }
.progress-orb small { text-align: center; font-family: var(--font-display); font-size: 5.5px; line-height: 1.5; letter-spacing: .12em; color: #849bb5; }

.level-grid { display: grid; grid-template-columns: repeat(4, minmax(220px, 1fr)); gap: 13px; }
.level-card {
  position: relative; display: flex; flex-direction: column; height: 224px; text-align: left;
  border: 1px solid rgba(160, 215, 255, .14); border-radius: 8px; overflow: hidden;
  background: #071022; transition: transform .24s var(--ease), border-color .24s, box-shadow .24s;
}
.level-card:hover { transform: translateY(-5px); border-color: color-mix(in srgb, var(--ca) 60%, white 10%); box-shadow: 0 18px 44px rgba(0,0,0,.43), 0 0 32px color-mix(in srgb, var(--ca) 14%, transparent); }
.level-art {
  position: relative; height: 132px; overflow: hidden;
  background:
    radial-gradient(circle at 60% 48%, color-mix(in srgb, var(--ca) 38%, transparent), transparent 46%),
    linear-gradient(130deg, var(--c1), var(--c2) 70%, var(--c1));
}
.level-art::before {
  content: ''; position: absolute; inset: -30% -10% -40%;
  background-image: linear-gradient(color-mix(in srgb, var(--ca) 18%, transparent) 1px, transparent 1px), linear-gradient(90deg, color-mix(in srgb, var(--ca) 18%, transparent) 1px, transparent 1px);
  background-size: 21px 21px; transform: perspective(160px) rotateX(57deg) translateY(34px); opacity: .8;
}
.level-art::after {
  content: ''; position: absolute; inset: 0;
  background: linear-gradient(180deg, transparent 55%, rgba(5,10,24,.65));
}
.card-num { position: absolute; top: 10px; left: 12px; z-index: 2; font-family: var(--font-display); font-size: 8px; letter-spacing: .13em; color: rgba(240,252,255,.7); }
.card-diff { position: absolute; top: 9px; right: 9px; z-index: 2; font-family: var(--font-display); font-size: 6px; letter-spacing: .12em; padding: 4px 6px; border-radius: 3px; background: rgba(0,0,0,.35); border: 1px solid color-mix(in srgb, var(--dc) 55%, transparent); color: var(--dc); }
.card-shape {
  position: absolute; left: 50%; top: 50%; z-index: 1; transform: translate(-50%, -50%);
  font-size: 52px; line-height: 1; color: #fff; text-shadow: 0 0 22px var(--ca), 0 4px 30px rgba(0,0,0,.55);
  opacity: .95;
}
.card-shape::after { content: ''; position: absolute; left: 50%; top: 50%; width: 92px; height: 92px; transform: translate(-50%,-50%) rotate(45deg); border: 1px solid color-mix(in srgb, var(--ca) 55%, transparent); box-shadow: 0 0 20px color-mix(in srgb, var(--ca) 20%, transparent); }
.card-best { position: absolute; bottom: 8px; right: 10px; z-index: 2; font-family: var(--font-display); font-size: 6px; letter-spacing: .1em; color: rgba(230,250,255,.8); }
.card-best.done { color: var(--green); }
.level-info { flex: 1; padding: 11px 12px 10px; display: flex; flex-direction: column; gap: 4px; background: rgba(5, 10, 23, .92); }
.level-info h3 { font-family: var(--font-display); font-size: 8.5px; letter-spacing: .1em; font-weight: 500; text-transform: uppercase; color: #e6f7ff; }
.level-info p { font-size: 10.5px; line-height: 1.15; color: #7588a1; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.card-progress { height: 2px; background: rgba(150,210,255,.12); margin-top: auto; overflow: hidden; }
.card-progress i { display: block; height: 100%; background: var(--ca); box-shadow: 0 0 8px var(--ca); }
.card-stars { display: flex; justify-content: space-between; align-items: center; font-family: var(--font-display); font-size: 6.5px; letter-spacing: .08em; color: #647b96; }
.card-stars b { color: var(--gold); font-weight: 500; }
.custom-section { margin-top: 34px; }
.section-line { display: flex; align-items: center; gap: 15px; margin-bottom: 16px; font-family: var(--font-display); font-size: 8px; letter-spacing: .2em; color: #93a9c2; }
.section-line i { flex: 1; height: 1px; background: rgba(150,210,255,.13); }
.custom-grid .level-card { height: 205px; }
.new-level-card { display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 9px; border-style: dashed; color: #7f98b4; background: rgba(8,16,34,.45); }
.new-level-card:hover { color: var(--cyan); border-color: rgba(46,230,255,.45); }
.new-level-card b { font-family: var(--font-display); font-size: 26px; font-weight: 500; color: var(--cyan); }
.new-level-card span { font-family: var(--font-display); font-size: 8px; letter-spacing: .15em; }

/* ============================== SKINS ============================== */
.skins-body { flex: 1; display: grid; grid-template-columns: 370px minmax(0, 1fr); gap: 26px; padding: 24px 3.6vw 40px; overflow-y: auto; }
.skin-preview-card {
