.preview-badge { position: relative; z-index: 1; align-self: flex-start; font-family: var(--font-display); font-size: 6px; letter-spacing: .16em; color: #8aa3be; border: 1px solid rgba(150,210,255,.15); padding: 4px 7px; border-radius: 3px; }
#skinPreview { position: relative; z-index: 1; width: 100%; max-width: 340px; aspect-ratio: 1; margin: 0 auto; display: block; }
.preview-glow { position: absolute; z-index: 0; left: 50%; top: 23%; width: 250px; height: 250px; transform: translate(-50%,-50%); border-radius: 50%; background: radial-gradient(circle, var(--pv, #2ee6ff), transparent 63%); opacity: .13; filter: blur(10px); }
.preview-name-row { position: relative; z-index: 1; display: flex; align-items: flex-end; justify-content: space-between; padding-top: 2px; }
.preview-name-row h2 { font-family: var(--font-display); font-size: 22px; letter-spacing: .03em; font-weight: 900; margin-top: 3px; }
.rarity-pill { font-family: var(--font-display); font-size: 6px; letter-spacing: .12em; color: #9effd2; border: 1px solid rgba(66,245,167,.3); padding: 4px 8px; border-radius: 20px; }
.skin-note { position: relative; z-index: 1; color: #8196af; font-size: 13px; line-height: 1.25; margin-top: 6px; min-height: 20px; }
.color-lab { position: relative; z-index: 1; margin-top: 16px; padding-top: 13px; border-top: 1px solid rgba(145,210,255,.13); }
.color-head { display: flex; justify-content: space-between; align-items: center; font-family: var(--font-display); font-size: 6.5px; letter-spacing: .17em; color: #9eb5cd; margin-bottom: 10px; }
.text-btn { font-family: var(--font-display); font-size: 6.5px; letter-spacing: .1em; color: var(--cyan); }
.text-btn:hover { text-shadow: 0 0 10px var(--cyan); }
.color-row { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }
.color-field { display: flex; flex-direction: column; gap: 5px; cursor: pointer; }
.color-field span { font-family: var(--font-display); font-size: 5.5px; letter-spacing: .13em; color: #778faa; }
.color-field input { position: absolute; opacity: 0; pointer-events: none; }
.color-field i { display: block; height: 29px; border-radius: 5px; border: 1px solid rgba(255,255,255,.25); background: var(--c); box-shadow: inset 0 0 0 3px rgba(0,0,0,.22); }
.preset-row { display: flex; gap: 6px; margin-top: 10px; flex-wrap: wrap; }
.preset-swatch { width: 20px; height: 20px; border-radius: 50%; border: 2px solid rgba(255,255,255,.13); background: conic-gradient(var(--a) 0 50%, var(--b) 50% 100%); transition: transform .2s; }
.preset-swatch:hover { transform: scale(1.16); border-color: rgba(255,255,255,.5); }
.skin-preview-card .btn.wide { margin-top: 15px; min-height: 43px; font-size: 8px; justify-content: space-between; padding: 0 16px; }
.skins-list-wrap { min-width: 0; }
.skins-list-head { display: flex; justify-content: space-between; padding: 4px 1px 11px; border-bottom: 1px solid rgba(145,210,255,.14); font-family: var(--font-display); font-size: 6.5px; letter-spacing: .18em; color: #748ba6; }
.skin-grid { display: grid; grid-template-columns: repeat(4, minmax(118px, 1fr)); gap: 10px; margin-top: 14px; }
.skin-card {
  position: relative; padding: 8px 8px 9px; border: 1px solid rgba(145,210,255,.12); border-radius: 7px;
  background: linear-gradient(150deg, rgba(14,25,48,.8), rgba(5,10,23,.8)); text-align: left;
  transition: .2s var(--ease); overflow: hidden;
}
.skin-card:hover { border-color: rgba(150,230,255,.4); transform: translateY(-2px); }
.skin-card.equipped { border-color: color-mix(in srgb, var(--sa) 65%, white 10%); box-shadow: 0 0 22px color-mix(in srgb, var(--sa) 16%, transparent), inset 0 0 18px color-mix(in srgb, var(--sa) 7%, transparent); }
.skin-card canvas { width: 100%; aspect-ratio: 1.3; display: block; }
.skin-card h4 { font-family: var(--font-display); font-size: 7px; letter-spacing: .11em; text-transform: uppercase; font-weight: 500; }
.skin-card small { font-family: var(--font-display); font-size: 5px; letter-spacing: .1em; color: #69809a; }
.equipped-tag { position: absolute; top: 5px; right: 5px; font-family: var(--font-display); font-size: 4.5px; letter-spacing: .08em; color: #061017; background: var(--sa); padding: 2px 4px; border-radius: 2px; }
.free-banner {
  display: flex; gap: 14px; align-items: center; margin-top: 16px; padding: 15px 17px;
  border: 1px solid rgba(66,245,167,.14); border-radius: 8px; background: rgba(25,100,75,.07);
}
.free-icon { font-family: var(--font-display); font-size: 30px; color: var(--green); text-shadow: 0 0 20px rgba(66,245,167,.5); }
.free-banner b { display: block; font-family: var(--font-display); font-size: 8px; letter-spacing: .14em; color: #9effd1; }
.free-banner p { color: #6f8f84; font-size: 12px; margin-top: 3px; }

/* ============================== EDITOR ============================== */
.editor-screen { pointer-events: none; background: radial-gradient(ellipse at 50% 50%, transparent 30%, rgba(1,3,10,.42) 100%); }
.ui-panel {
  pointer-events: auto; border: 1px solid rgba(145,210,255,.16); border-radius: 8px;
  background: rgba(5, 11, 26, .86); backdrop-filter: var(--glass-blur); -webkit-backdrop-filter: var(--glass-blur);
  box-shadow: 0 18px 50px rgba(0,0,0,.36);
}
.editor-topbar { position: absolute; top: 14px; left: 16px; right: 16px; height: 61px; display: flex; align-items: center; gap: 18px; padding: 0 15px; z-index: 4; }
.editor-title { display: flex; flex-direction: column; gap: 4px; min-width: 210px; }
.level-name-input {
  width: 210px; padding: 0; border: 0; border-bottom: 1px solid transparent; outline: 0;
