  color: #e9f9ff;
}
.level-name-input:focus { border-bottom-color: var(--cyan); }
.editor-top-actions { margin-left: auto; display: flex; align-items: center; gap: 7px; }
.save-state { font-family: var(--font-display); font-size: 5.5px; letter-spacing: .1em; color: #637b96; margin-right: 5px; white-space: nowrap; }
.save-state.saved { color: var(--green); }
.editor-tools { position: absolute; top: 92px; left: 16px; width: 145px; padding: 12px; z-index: 4; display: flex; flex-direction: column; gap: 6px; }
.panel-label { font-family: var(--font-display); font-size: 6.5px; letter-spacing: .2em; color: #7189a3; margin: 1px 2px 5px; }
.tool-btn {
  display: flex; align-items: center; gap: 8px; min-height: 34px; padding: 0 7px;
  border: 1px solid transparent; border-radius: 5px; background: rgba(140,200,255,.035);
  color: #9cb2ca; font-family: var(--font-body); font-size: 12px; text-align: left; transition: .16s;
}
.tool-btn b { font-weight: 600; flex: 1; }
.tool-btn kbd { font-family: var(--font-display); font-size: 5.5px; color: #5d748d; background: rgba(140,200,255,.08); border-radius: 2px; padding: 2px 4px; }
.tool-btn:hover { border-color: rgba(145,210,255,.2); color: #dff7ff; background: rgba(140,200,255,.08); }
.tool-btn.active { border-color: rgba(46,230,255,.45); color: #e9fcff; background: rgba(46,230,255,.1); }
.tool-btn.active kbd { color: var(--cyan); }
.tool-ico { width: 18px; height: 18px; display: grid; place-items: center; color: var(--cyan); font-size: 12px; flex: 0 0 auto; }
.spike-ico::before { content: '▲'; color: var(--cyan); }
.block-ico::before { content: '■'; color: #9db8d1; }
.gate-ico::before { content: '▮'; color: var(--pink); font-size: 17px; }
.saw-ico::before { content: '✹'; color: var(--pink); }
.hurdle-ico::before { content: '━'; color: var(--pink); font-size: 19px; }
.pad-ico::before { content: '◉'; color: var(--gold); }
.coin-ico::before { content: '◎'; color: var(--gold); }
.finish-ico::before { content: '⏻'; color: var(--green); }
.erase-ico::before { content: '⌫'; color: #ff8b9e; }
.finish-tool { margin-top: 3px; border-top: 1px solid rgba(145,210,255,.1); border-radius: 0 0 5px 5px; }
.erase-tool { color: #c98e9a; }
.editor-inspector { position: absolute; top: 92px; right: 16px; width: 232px; padding: 14px 14px 15px; z-index: 4; }
.field-label { display: flex; justify-content: space-between; margin: 12px 1px 5px; font-family: var(--font-display); font-size: 5.5px; letter-spacing: .14em; color: #6f88a2; }
.field-label span { color: var(--cyan); }
.select {
  width: 100%; height: 34px; padding: 0 9px; border-radius: 5px; outline: none;
  border: 1px solid rgba(145,210,255,.17); background: #081125; color: #dff7ff;
  font-size: 12px; font-weight: 600; letter-spacing: .02em;
}
.theme-swatch-row { display: flex; gap: 5px; margin-top: 7px; }
.theme-swatch-row i { flex: 1; height: 5px; border-radius: 10px; background: var(--sw); box-shadow: 0 0 10px color-mix(in srgb, var(--sw) 45%, transparent); }
.range { -webkit-appearance: none; appearance: none; width: 100%; height: 3px; margin: 10px 0 0; border-radius: 5px; background: rgba(145,210,255,.17); outline: none; }
.range::-webkit-slider-thumb { -webkit-appearance: none; width: 12px; height: 12px; border-radius: 50%; background: var(--cyan); box-shadow: 0 0 12px rgba(46,230,255,.7); cursor: pointer; }
.range::-moz-range-thumb { width: 12px; height: 12px; border: 0; border-radius: 50%; background: var(--cyan); box-shadow: 0 0 12px rgba(46,230,255,.7); cursor: pointer; }
.editor-stats { display: flex; gap: 10px; margin-top: 15px; padding-top: 12px; border-top: 1px solid rgba(145,210,255,.12); }
.editor-stats div { flex: 1; display: flex; flex-direction: column; gap: 1px; }
.editor-stats b { font-family: var(--font-display); font-size: 13px; }
.editor-stats span { font-family: var(--font-display); font-size: 5px; letter-spacing: .12em; color: #728aa5; }
.editor-help { margin-top: 14px; padding-top: 12px; border-top: 1px solid rgba(145,210,255,.12); }
.editor-help b { font-family: var(--font-display); font-size: 5.5px; letter-spacing: .14em; color: #849bb5; }
.editor-help p { display: flex; justify-content: space-between; margin: 5px 0 0; font-size: 10px; color: #617993; }
.editor-help p span { font-family: var(--font-display); font-size: 5.5px; color: #a6bfd8; }
.editor-bottom { position: absolute; bottom: 14px; left: 177px; right: 264px; height: 57px; display: flex; align-items: center; gap: 11px; padding: 0 13px; z-index: 4; }
.round-btn { width: 31px; height: 31px; flex: 0 0 auto; border-radius: 50%; border: 1px solid rgba(145,210,255,.2); color: var(--cyan); font-size: 10px; }
.round-btn:hover { background: rgba(46,230,255,.12); }
.timeline-wrap { flex: 1; min-width: 0; }
.timeline-labels { display: flex; justify-content: space-between; padding: 0 2px; font-family: var(--font-display); font-size: 5px; letter-spacing: .1em; color: #657d97; }
.timeline-labels span:nth-child(2) { color: var(--cyan); }
.timeline-range { margin-top: 5px; }
.editor-hint { font-family: var(--font-display); font-size: 5.5px; letter-spacing: .09em; color: #617993; white-space: nowrap; display: flex; align-items: center; }
.editor-hint .key { height: 18px; min-width: 20px; margin: 0 3px 0 7px; }
.cursor-info {
  position: absolute; bottom: 78px; left: 50%; transform: translateX(-50%);
  padding: 5px 10px; border-radius: 3px; background: rgba(5,10,24,.75); border: 1px solid rgba(145,210,255,.16);
  font-family: var(--font-display); font-size: 5.5px; letter-spacing: .13em; color: #91a9c2; z-index: 3; pointer-events: none;
}

/* ============================== HUD ============================== */
.hud { position: fixed; inset: 0; z-index: 20; pointer-events: none; }
.hud-top {
  position: absolute; top: 16px; left: 18px; right: 18px; height: 58px;
  display: flex; align-items: center; gap: 15px; padding: 0 14px;
  border: 1px solid rgba(145,210,255,.15); border-radius: 8px;
  background: linear-gradient(180deg, rgba(5,11,26,.76), rgba(5,11,26,.42));
  backdrop-filter: blur(13px); -webkit-backdrop-filter: blur(13px);
}
.hud-top > * { pointer-events: auto; }
.hud-icon { width: 36px; height: 36px; flex: 0 0 auto; border-radius: 6px; border: 1px solid rgba(145,210,255,.17); color: #b4d0e8; font-family: var(--font-display); font-size: 10px; display: grid; place-items: center; }
.hud-icon:hover { color: #fff; background: rgba(46,230,255,.1); }
.hud-level { display: flex; align-items: center; gap: 9px; min-width: 150px; }
.hud-num { font-family: var(--font-display); font-size: 15px; color: var(--cyan); font-weight: 900; }
.hud-level > div { display: flex; flex-direction: column; gap: 1px; }
.hud-diff { font-family: var(--font-display); font-size: 5px; letter-spacing: .14em; color: var(--dc, var(--green)); }
.hud-level b { font-family: var(--font-display); font-size: 7px; letter-spacing: .11em; font-weight: 500; text-transform: uppercase; white-space: nowrap; }
.hud-progress-wrap { flex: 1; max-width: 540px; margin: 0 auto; }
.hud-progress { position: relative; height: 8px; border-radius: 10px; background: rgba(140,200,255,.12); overflow: visible; }
.hud-progress i { display: block; height: 100%; width: 0%; border-radius: 10px; background: linear-gradient(90deg, #24cfff, #7df9ff); box-shadow: 0 0 16px rgba(46,230,255,.45); transition: width .08s linear; }
.hud-progress span { position: absolute; top: -5px; left: 50%; transform: translateX(-50%); font-family: var(--font-display); font-size: 8px; font-weight: 900; color: #e9feff; text-shadow: 0 1px 6px rgba(0,0,0,.7); }
.hud-subline { display: flex; justify-content: space-between; margin-top: 5px; font-family: var(--font-display); font-size: 5px; letter-spacing: .13em; color: #67819c; }
.hud-subline #hudPractice { color: var(--gold); }
.hud-right { margin-left: auto; display: flex; align-items: center; gap: 12px; }
.coin-counter { display: flex; align-items: center; gap: 7px; font-family: var(--font-display); font-size: 9px; color: #ffdf8e; }
.coin-counter i { width: 10px; height: 10px; border: 2px solid #ffd166; border-radius: 50%; box-shadow: 0 0 9px rgba(255,209,102,.5); }
.jump-hint {
  position: absolute; bottom: 24px; left: 50%; transform: translateX(-50%);
  font-family: var(--font-display); font-size: 6px; letter-spacing: .14em; color: #7390ad;
  display: flex; align-items: center; gap: 4px; pointer-events: none;
  transition: opacity .5s;
}
.jump-hint .key { height: 20px; }
.jump-hint .divider { margin: 0 8px; color: #40546b; }
.checkpoint-toast {
  position: absolute; top: 95px; left: 50%; transform: translateX(-50%);
  padding: 7px 14px; border-radius: 4px; border: 1px solid rgba(255,209,102,.35);
  background: rgba(26,20,4,.7); color: var(--gold); font-family: var(--font-display); font-size: 6.5px; letter-spacing: .17em;
  animation: toastIn .4s ease both;
}
.checkpoint-toast span { color: #fff; margin-left: 4px; }
@keyframes toastIn { from { opacity: 0; transform: translate(-50%, -8px); } }
.touch-controls { display: none; position: absolute; left: 0; right: 0; bottom: 16px; padding: 0 17px; justify-content: space-between; pointer-events: none; }
.touch-btn { pointer-events: auto; width: 64px; height: 64px; border-radius: 50%; border: 1px solid rgba(145,210,255,.24); background: rgba(7,14,30,.55); backdrop-filter: blur(8px); color: #cdefff; font-family: var(--font-display); font-size: 8px; touch-action: none; }
.touch-jump { width: 86px; height: 86px; border-color: rgba(46,230,255,.45); background: rgba(9,45,68,.55); box-shadow: 0 0 28px rgba(46,230,255,.15); }
.touch-btn:active { background: rgba(46,230,255,.22); }

/* ============================== MODALS ============================== */
.modal-layer {
  position: fixed; inset: 0; z-index: 40; display: flex; align-items: center; justify-content: center;
  background: radial-gradient(ellipse at 50% 40%, rgba(10,24,45,.58), rgba(1,2,8,.9));
  backdrop-filter: blur(14px); -webkit-backdrop-filter: blur(14px);
  animation: modalFade .28s ease both;
}
@keyframes modalFade { from { opacity: 0; } }
.modal {
  position: relative; width: min(92vw, 480px); padding: 31px 34px 27px;
  border: 1px solid rgba(145,215,255,.21); border-radius: 12px;
  background: linear-gradient(155deg, rgba(10,20,42,.97), rgba(4,8,20,.98));
  box-shadow: 0 35px 120px rgba(0,0,0,.65), inset 0 1px 0 rgba(255,255,255,.06), 0 0 70px rgba(46,230,255,.05);
  text-align: center; animation: modalIn .35s var(--ease) both;
}
@keyframes modalIn { from { opacity: 0; transform: translateY(22px) scale(.97); } }
.modal h2 { font-family: var(--font-display); font-size: 27px; font-weight: 900; letter-spacing: .01em; margin: 8px 0 0; }
.modal-sub { color: #8299b3; font-size: 14px; margin-top: 7px; }
.modal .kicker { text-align: center; }
.modal-actions { display: flex; flex-direction: column; gap: 8px; margin-top: 21px; }
.modal-actions .btn { width: 100%; justify-content: space-between; min-height: 47px; padding: 0 18px; }
.modal-actions .btn-primary { justify-content: space-between; }
.pause-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; margin: 20px 0 15px; }
.pause-stats div { padding: 13px 5px 11px; border: 1px solid rgba(145,210,255,.12); border-radius: 6px; background: rgba(100,180,255,.04); }
.pause-stats b { display: block; font-family: var(--font-display); font-size: 16px; color: #e9fcff; }
.pause-stats span { font-family: var(--font-display); font-size: 5.5px; letter-spacing: .15em; color: #6f88a3; }
.toggle-row {
  display: flex; align-items: center; justify-content: space-between; gap: 15px; text-align: left;
  padding: 12px 14px; border: 1px solid rgba(145,210,255,.13); border-radius: 6px; background: rgba(100,180,255,.035); cursor: pointer;
}
.toggle-row span { display: flex; flex-direction: column; gap: 2px; }
.toggle-row b { font-family: var(--font-display); font-size: 7px; letter-spacing: .13em; }
.toggle-row small { color: #7188a1; font-size: 11px; }
.toggle-row input { display: none; }
.toggle { position: relative; width: 37px; height: 20px; border-radius: 20px; background: rgba(130,180,220,.18); border: 1px solid rgba(145,210,255,.2); flex: 0 0 auto; transition: .2s; }
.toggle::after { content: ''; position: absolute; width: 14px; height: 14px; border-radius: 50%; left: 2px; top: 2px; background: #8099b4; transition: .2s var(--ease); }
.toggle-row input:checked + .toggle { background: rgba(46,230,255,.3); border-color: rgba(46,230,255,.6); }
.toggle-row input:checked + .toggle::after { left: 19px; background: var(--cyan); box-shadow: 0 0 10px var(--cyan); }

.death-modal { border-color: rgba(255,77,103,.3); box-shadow: 0 35px 120px rgba(0,0,0,.68), 0 0 80px rgba(255,45,80,.08); }
.death-icon { width: 47px; height: 47px; margin: -57px auto 13px; border: 1px solid rgba(255,77,103,.6); border-radius: 50%; color: var(--red); background: #0b0710; display: grid; place-items: center; font-size: 17px; box-shadow: 0 0 30px rgba(255,45,80,.22), inset 0 0 15px rgba(255,45,80,.13); }
.death-modal .kicker { color: var(--red); }
.death-modal h2 { font-size: 31px; color: #ffe9ed; }
.pct-display { margin: 17px 0 8px; font-family: var(--font-display); font-size: 61px; line-height: 1; font-weight: 900; color: #fff; text-shadow: 0 0 42px rgba(255,77,103,.38); }
.pct-display small { font-size: 22px; color: var(--red); margin-left: 3px; }
.death-bar { position: relative; height: 4px; background: rgba(255,255,255,.09); border-radius: 5px; margin-bottom: 8px; }
.death-bar i { display: block; height: 100%; border-radius: 5px; background: linear-gradient(90deg, #ff335f, #ff8aa0); box-shadow: 0 0 12px rgba(255,60,100,.5); }
.death-bar b { position: absolute; right: 0; top: -15px; font-family: var(--font-display); font-size: 5.5px; letter-spacing: .12em; color: #8098b0; font-weight: 500; }
.death-meta { display: flex; justify-content: space-between; font-family: var(--font-display); font-size: 5.5px; letter-spacing: .12em; color: #6e849d; margin-top: 13px; }

.win-modal { border-color: rgba(46,230,255,.32); overflow: hidden; }
.win-modal .kicker { color: var(--cyan); }
.win-title { font-family: var(--font-display); font-size: 45px; line-height: 1; font-weight: 900; margin-top: 10px; letter-spacing: -.03em; background: linear-gradient(180deg, #fff, #5eeaff 65%, #1389dd); -webkit-background-clip: text; background-clip: text; color: transparent; filter: drop-shadow(0 0 24px rgba(46,230,255,.3)); }
.win-title span { display: block; font-size: 18px; letter-spacing: .35em; margin-top: 5px; color: var(--pink); -webkit-text-fill-color: var(--pink); filter: none; }
.win-modal h2 { font-size: 12px; color: #b9d8e9; letter-spacing: .16em; margin-top: 12px; }
.win-stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: 5px; margin: 18px 0 11px; }
