    if (this.camera.fov !== 62) { this.camera.fov = 62; this.camera.updateProjectionMatrix(); }
    const target = new THREE.Vector3(p.x * 0.24 + 0.35, 5.0 + p.y * 0.13, p.z - 10.0);
