340:   const full = c.length === 3 ? c.split('').map(x => x + x).join('') : c;
341:   const n = parseInt(full, 16);
342:   let r = (n >> 16) & 255, g = (n >> 8) & 255, b = n & 255;
343:   r = clamp(Math.round(r + amt), 0, 255);
344:   g = clamp(Math.round(g + amt), 0, 255);
345:   b = clamp(Math.round(b + amt), 0, 255);
346:   return '#' + [r, g, b].map(v => v.toString(16).padStart(2, '0')).join('');
347: }
