349: function drawSkin(cv, skinId, colors, big = false) {
350:   const skin = SKIN_BY_ID[skinId] || SKIN_BY_ID.classic;
351:   const ctx = cv.getContext('2d');
352:   const w = cv.width, h = cv.height;
353:   ctx.clearRect(0, 0, w, h);
354:   const cx = w / 2, cy = h * (big ? 0.49 : 0.56);
355:   const s = Math.min(w, h) * (big ? 0.21 : 0.24);
356:   const p = colors.primary;
357:   const sec = colors.secondary;
358:   const glow = colors.glow;
359: 
360:   const rg = ctx.createRadialGradient(cx, cy, 2, cx, cy, s * 3.6);
361:   rg.addColorStop(0, hexA(glow, 0.33));
362:   rg.addColorStop(0.48, hexA(glow, 0.08));
363:   rg.addColorStop(1, hexA(glow, 0));
364:   ctx.fillStyle = rg; ctx.fillRect(0, 0, w, h);
365: 
366:   // floor shadow + orbit ring
367:   ctx.save();
368:   ctx.translate(cx, cy + s * 1.45);
369:   ctx.scale(1, 0.28);
370:   const sh = ctx.createRadialGradient(0, 0, 0, 0, 0, s * 1.35);
371:   sh.addColorStop(0, 'rgba(0,0,0,.6)'); sh.addColorStop(1, 'rgba(0,0,0,0)');
372:   ctx.fillStyle = sh; ctx.beginPath(); ctx.arc(0, 0, s * 1.35, 0, Math.PI * 2); ctx.fill();
373:   ctx.restore();
374: 
375:   ctx.strokeStyle = hexA(sec, big ? 0.35 : 0.25);
376:   ctx.lineWidth = big ? 1.5 : 1;
377:   ctx.beginPath(); ctx.ellipse(cx, cy + s * 0.5, s * 1.75, s * 0.42, -0.18, 0, Math.PI * 2); ctx.stroke();
378:   ctx.strokeStyle = hexA(glow, 0.26);
379:   ctx.beginPath(); ctx.ellipse(cx, cy + s * 0.5, s * 1.4, s * 1.45, 0.5, 0, Math.PI * 2); ctx.stroke();
380: 
381:   ctx.save();
382:   ctx.translate(cx, cy);
383:   const line = big ? 3 : 1.8;
384:   ctx.lineWidth = line;
385:   ctx.strokeStyle = sec;
386:   ctx.lineJoin = 'round';
387: 
388:   const poly = (pts, fill) => {
389:     ctx.beginPath(); pts.forEach(([x, y], i) => i ? ctx.lineTo(x, y) : ctx.moveTo(x, y)); ctx.closePath();
390:     ctx.fillStyle = fill; ctx.fill(); ctx.stroke();
391:   };
392: 
393:   if (skin.shape === 'box') {
394:     const d = s;
395:     poly([[0, -d], [d * .95, -d * .5], [0, 0], [-d * .95, -d * .5]], shade(p, 45));
396:     poly([[-d * .95, -d * .5], [0, 0], [0, d * 1.1], [-d * .95, d * .55]], shade(p, -58));
397:     poly([[0, 0], [d * .95, -d * .5], [d * .95, d * .55], [0, d * 1.1]], p);
398:     ctx.strokeStyle = hexA(sec, .9); ctx.stroke();
399:   } else if (skin.shape === 'octa') {
400:     poly([[0, -s], [s * .86, 0], [0, 0]], shade(p, 38));
401:     poly([[0, -s], [-s * .86, 0], [0, 0]], shade(p, 5));
402:     poly([[0, 0], [s * .86, 0], [0, s]], shade(p, -45));
403:     poly([[0, 0], [-s * .86, 0], [0, s]], shade(p, -20));
404:   } else if (skin.shape === 'sphere') {
405:     const g = ctx.createRadialGradient(-s * .3, -s * .35, s * .05, 0, 0, s * 1.05);
406:     g.addColorStop(0, shade(p, 75)); g.addColorStop(.5, p); g.addColorStop(1, shade(p, -80));
407:     ctx.beginPath(); ctx.arc(0, 0, s * .95, 0, Math.PI * 2);
408:     ctx.fillStyle = g; ctx.fill(); ctx.stroke();
409:     ctx.strokeStyle = hexA(sec, .25);
410:     ctx.beginPath(); ctx.ellipse(0, 0, s * .95, s * .3, -0.25, 0, Math.PI * 2); ctx.stroke();
411:   } else if (skin.shape === 'hex') {
412:     const pts = []; for (let i = 0; i < 6; i++) { const a = -Math.PI / 2 + i * Math.PI / 3; pts.push([Math.cos(a) * s, Math.sin(a) * s]); }
413:     poly(pts, p);
414:     ctx.strokeStyle = hexA(sec, .5);
415:     ctx.beginPath(); ctx.arc(0, 0, s * .55, 0, Math.PI * 2); ctx.stroke();
416:   } else if (skin.shape === 'star') {
417:     const pts = []; for (let i = 0; i < 10; i++) { const a = -Math.PI / 2 + i * Math.PI / 5; const r = i % 2 ? s * .47 : s * 1.12; pts.push([Math.cos(a) * r, Math.sin(a) * r]); }
418:     poly(pts, p);
419:     poly([[0, -s * .65], [s * .42, 0], [0, s * .65], [-s * .42, 0]], shade(p, 42));
420:   } else {
421:     poly([[0, -s * 1.08], [s * .82, s * .32], [0, s * .2], [-s * .82, s * .32]], p);
422:     poly([[0, s * .2], [s * .82, s * .32], [0, s * 1.02]], shade(p, -56));
423:     poly([[0, s * .2], [-s * .82, s * .32], [0, s * 1.02]], shade(p, -28));
424:   }
425: 
426:   // icon
427:   ctx.save();
428:   ctx.globalAlpha = 0.94;
429:   ctx.fillStyle = sec;
430:   ctx.strokeStyle = sec;
431:   ctx.textAlign = 'center';
432:   ctx.textBaseline = 'middle';
433:   ctx.shadowColor = sec;
434:   ctx.shadowBlur = big ? 16 : 8;
435:   ctx.font = `900 ${Math.round(s * (skin.shape === 'box' ? .8 : .68))}px Orbitron, Arial Black, sans-serif`;
436:   ctx.fillText(ICON_GLYPHS[skin.icon] || '◆', 0, s * .34);
437:   ctx.restore();
438:   ctx.restore();
439: 
440:   // sparkles
441:   ctx.fillStyle = hexA(sec, .55);
442:   const rng = mulberry32(skin.id.length * 999 + profile.primary.length);
443:   for (let i = 0; i < (big ? 14 : 5); i++) {
444:     const a = rng() * Math.PI * 2, r = s * (1.3 + rng() * 1.4);
445:     ctx.globalAlpha = .15 + rng() * .35;
446:     ctx.fillRect(cx + Math.cos(a) * r, cy + Math.sin(a) * r * .7, big ? 2 : 1, big ? 2 : 1);
447:   }
448:   ctx.globalAlpha = 1;
449: }
