782:   }
783:   editor.draft.events.sort((a, b) => a.z - b.z || a.lane - b.lane);
784:   editor.viewZ = clamp(48, 12, editor.draft.length - 20);
785:   state = 'editor';
786:   document.body.classList.add('in-editor');
