799:   $('levelNameInput').value = d.name;
800:   $('themeSelect').innerHTML = THEMES.map(t => `<option value="${t.id}">${esc(t.name)} · ${t.difficulty}</option>`).join('');
801:   $('themeSelect').value = d.themeId;
802:   $('lengthRange').value = d.length;
