881: function placeObject(point, erase = false) {
882:   if (!editor.draft || !point) return;
883:   let { lane, z } = point;
884:   const tool = erase ? 'erase' : editor.tool;
885:   const events = editor.draft.events;
886: 
887:   if (erase) {
888:     const before = events.length;
889:     editor.draft.events = events.filter(e => {
890:       if (e.type === 'finish') return Math.abs(e.z - z) > 2.5;
891:       if (e.type === 'hurdle') return Math.abs(e.z - z) > 1.6;
892:       return !(Math.abs(e.z - z) < 1.5 && e.lane === lane);
893:     });
894:     if (before === editor.draft.events.length) return;
895:     markDirty(true);
896:     showToast('OBJECT REMOVED');
897:     return;
898:   }
899: 
900:   if (tool === 'finish') {
901:     lane = 0;
902:     editor.draft.events = events.filter(e => e.type !== 'finish');
903:     editor.draft.events.push({ type: 'finish', lane, z });
904:     if (z + 24 > editor.draft.length) {
905:       editor.draft.length = clamp(z + 40, 220, 1200);
906:       $('lengthRange').value = editor.draft.length;
907:       $('lengthValue').textContent = editor.draft.length;
