913:     }
914:     saveDraft(true);
915:     commitCustomLevel(true);
916:     showToast('FINISH LINE MOVED');
917:     return;
918:   }
919: 
920:   // remove anything already in this cell
921:   editor.draft.events = events.filter(e => {
922:     if (tool === 'hurdle') return e.type !== 'hurdle' || Math.abs(e.z - z) > 1.2;
923:     return !(e.lane === lane && Math.abs(e.z - z) < 1.2 && e.type !== 'finish');
924:   });
