383:       color, emissive, emissiveIntensity: intensity,
384:       metalness: opts.metalness ?? 0.35, roughness: opts.roughness ?? 0.42,
385:       flatShading: !!opts.flat, transparent: !!opts.transparent,
386:       opacity: opts.opacity ?? 1, side: opts.side || THREE.FrontSide
387:     });
388:     if (opts.noCache) { this.materials.push(m); return m; }
389:     if (!this.matCache) this.matCache = new Map();
390:     this.matCache.set(key, m);
391:     this.materials.push(m);
392:     return m;
393:   }
