430:     this.scene.fog = new THREE.Fog(theme.colors.fog, 58, 225);
431:     this.skyUniforms.topColor.value.set(theme.colors.top);
432:     this.skyUniforms.bottomColor.value.set(theme.colors.bottom);
433:     this.lights.hemi.color.set(theme.colors.grid);
434:     this.lights.hemi.groundColor.set(theme.colors.deep);
435:     this.lights.key.color.set(theme.colors.text);
436:     this.lights.rim.color.set(theme.colors.accent2);
437:     this.lights.ambient.color.set(theme.colors.fog);
438:     this.matCache = new Map();
439:     this.makeStars(length, theme);
