442:   makeStars(length, theme) {
443:     const count = 1100;
444:     const pos = new Float32Array(count * 3);
445:     const rng = mulberry32(8701 + length);
446:     for (let i = 0; i < count; i++) {
447:       pos[i * 3] = (rng() - 0.5) * 380;
448:       pos[i * 3 + 1] = 3 + rng() * 160;
449:       pos[i * 3 + 2] = -80 + rng() * (length + 300);
450:     }
451:     const g = new THREE.BufferGeometry();
452:     g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
453:     const m = new THREE.PointsMaterial({ color: theme.colors.text, size: 0.55, transparent: true, opacity: 0.68, fog: false, depthWrite: false });
454:     this.stars = new THREE.Points(g, m);
455:     this.stars.frustumCulled = false;
456:     this.scene.add(this.stars);
457:   }
