459:   buildEnvironment(theme, length, options = {}) {
460:     this.applyTheme(theme, length);
461:     const env = this.environment;
462:     const c = theme.colors;
463: 
464:     // giant sun / halo
465:     const sunMat = new THREE.SpriteMaterial({ map: glowTexture(), color: c.accent, transparent: true, opacity: 0.55, blending: THREE.AdditiveBlending, depthWrite: false, fog: false });
466:     this.sun = new THREE.Sprite(sunMat);
467:     this.sun.position.set(-55, 36 + Math.sin(length) * 8, length * 0.52);
468:     this.sun.scale.set(92, 92, 1);
469:     this.scene.add(this.sun);
470: 
471:     // side ground
472:     const ground = new THREE.Mesh(
473:       new THREE.PlaneGeometry(420, length + 260),
474:       new THREE.MeshStandardMaterial({ color: c.deep, roughness: 0.9, metalness: 0.1 })
475:     );
476:     ground.rotation.x = -Math.PI / 2;
477:     ground.position.set(0, -1.0, length / 2 - 40);
478:     env.add(ground);
479:     this.materials.push(ground.material);
480: 
481:     const grid = new THREE.GridHelper(420, 105, c.grid, c.fog);
482:     grid.position.set(0, -0.96, length / 2 - 40);
483:     grid.material.transparent = true;
484:     grid.material.opacity = 0.16;
485:     grid.material.depthWrite = false;
486:     env.add(grid);
487:     this.materials.push(grid.material);
488: 
489:     // track base
490:     const trackMat = this.material('track', c.track, c.fog, 0.35, { metalness: 0.5, roughness: 0.55 });
491:     const track = new THREE.Mesh(new THREE.BoxGeometry(TRACK_WIDTH, 0.75, length + 130), trackMat);
492:     track.position.set(0, -0.38, length / 2 - 30);
493:     env.add(track);
494: 
495:     // lane dividers
496:     const lineMat = this.material('lane', c.grid, c.grid, 1.2, { transparent: true, opacity: 0.4, noCache: true });
497:     lineMat.transparent = true; lineMat.opacity = 0.42;
498:     for (const x of [-1.38, 1.38]) {
499:       const line = new THREE.Mesh(new THREE.BoxGeometry(0.045, 0.03, length + 120), lineMat);
500:       line.position.set(x, 0.012, length / 2 - 30);
501:       env.add(line);
502:     }
503:     // outer rails
504:     const railMat = this.material('rail', c.accent, c.accent, 1.05, { metalness: 0.7, roughness: 0.2, noCache: true });
505:     for (const x of [-TRACK_WIDTH / 2, TRACK_WIDTH / 2]) {
506:       const rail = new THREE.Mesh(new THREE.BoxGeometry(0.1, 0.18, length + 120), railMat);
507:       rail.position.set(x, 0.08, length / 2 - 30);
508:       env.add(rail);
509:       const side = new THREE.Mesh(new THREE.BoxGeometry(0.06, 1.2, length + 120), this.material('side', c.accent2, c.accent2, 0.7, { transparent: true, opacity: 0.24, noCache: true }));
510:       side.position.set(x + Math.sign(x) * 0.14, -0.8, length / 2 - 30);
511:       env.add(side);
512:     }
513: 
514:     // track panels
515:     const panelMat = this.material('panel', c.grid, c.grid, 0.6, { transparent: true, opacity: 0.14, noCache: true });
516:     panelMat.transparent = true; panelMat.opacity = 0.13;
517:     const panelGeo = new THREE.BoxGeometry(TRACK_WIDTH - 0.25, 0.02, 0.06);
518:     const count = Math.ceil((length + 100) / 12);
519:     const panels = new THREE.InstancedMesh(panelGeo, panelMat, count);
520:     const m4 = new THREE.Matrix4();
521:     for (let i = 0; i < count; i++) {
522:       m4.setPosition(0, 0.018, -30 + i * 12);
523:       panels.setMatrixAt(i, m4);
524:     }
525:     env.add(panels);
