541:     // outer beacons
542:     const beaconMat = this.material('beacon', c.accent, c.accent, 1.8, { noCache: true });
543:     for (let z = 18; z < length; z += 42) {
544:       for (const side of [-1, 1]) {
545:         const post = new THREE.Mesh(new THREE.BoxGeometry(0.1, 2.5, 0.1), beaconMat);
546:         post.position.set(side * 5.4, 1.25, z);
