555:   buildDecor(theme, length) {
556:     const env = this.environment;
557:     const decor = new THREE.Group();
558:     env.add(decor);
559:     this.decorGroup = decor;
560:     const c = theme.colors;
561:     const rng = mulberry32(theme.seed + 99);
562:     const add = (geo, mat, x, y, z, sx = 1, sy = 1, sz = 1, spin = 0.1) => {
563:       const m = new THREE.Mesh(geo, mat);
564:       m.position.set(x, y, z); m.scale.set(sx, sy, sz);
565:       decor.add(m);
566:       if (spin) this.animated.push({ obj: m, spin, baseY: y, bob: rng() * 2, amp: 0.2 + rng() * 0.5 });
567:       return m;
568:     };
569:     const dark = this.material('decorDark', c.deep, c.fog, 0.3, { roughness: 0.6, metalness: 0.45 });
570:     const accent = this.material('decorAccent', c.accent, c.accent, 1.35, { roughness: 0.25, metalness: 0.65 });
571:     const accent2 = this.material('decorAccent2', c.accent2, c.accent2, 1.35, { roughness: 0.25, metalness: 0.65 });
572:     const glass = this.material('decorGlass', c.grid, c.grid, 0.8, { transparent: true, opacity: 0.18, roughness: 0.1, metalness: 0.9 });
573: 
574:     const ring = (x, y, z, radius, tube, mat, rx = 0, ry = 0, rz = 0, spin = 0.05) => {
575:       const m = new THREE.Mesh(new THREE.TorusGeometry(radius, tube, 8, 64), mat);
576:       m.position.set(x, y, z); m.rotation.set(rx, ry, rz);
577:       decor.add(m);
578:       this.animated.push({ obj: m, spin, baseY: y, bob: rng() * 3, amp: 0.5 });
579:       return m;
580:     };
581: 
582:     if (theme.motif === 'city') {
583:       for (let i = 0; i < 36; i++) {
584:         const side = i % 2 ? 1 : -1;
585:         const z = 8 + rng() * (length + 40);
586:         const h = 3 + rng() * 19;
587:         const w = 1.2 + rng() * 4.4;
588:         const x = side * (9 + rng() * 25);
589:         add(new THREE.BoxGeometry(w, h, w), dark, x, h / 2 - 1.1, z, 1, 1, 1, 0.02);
590:         const strip = add(new THREE.BoxGeometry(w * 0.72, 0.07, 0.04), accent, x, h * 0.62 - 1.1, z - side * w / 2 - 0.02, 1, 1, 1, 0);
591:         if (rng() < 0.5) add(new THREE.BoxGeometry(0.07, h * 0.32, 0.04), accent2, x + w * 0.22, h * 0.34 - 1.1, z - side * w / 2 - 0.03, 1, 1, 1, 0);
592:       }
593:       for (let i = 0; i < 10; i++) {
594:         const side = i % 2 ? 1 : -1;
595:         ring(side * (13 + rng() * 30), 7 + rng() * 25, 20 + rng() * length, 2.5 + rng() * 6, 0.06, accent2, 0, rng() * 3, 0, 0.15);
596:       }
597:     } else if (theme.motif === 'rings') {
598:       for (let i = 0; i < 12; i++) {
599:         const side = i % 2 ? 1 : -1;
600:         ring(side * (19 + rng() * 28), 9 + rng() * 18, 15 + (i / 12) * (length + 60) + rng() * 20,
601:           5 + rng() * 11, 0.10 + rng() * 0.16, i % 3 ? accent : accent2, rng() * 1.2, rng() * 2, rng() * 1.5, 0.12 + rng() * 0.1);
602:       }
603:       for (let i = 0; i < 20; i++) {
604:         const side = i % 2 ? 1 : -1;
605:         add(new THREE.OctahedronGeometry(0.6 + rng() * 2.2), glass, side * (9 + rng() * 30), 3 + rng() * 22, 5 + rng() * length, 1, 1, 1, 0.4 + rng() * 0.4);
606:       }
607:     } else if (theme.motif === 'crystals') {
608:       const shardMat = this.material('crystal', c.accent, c.accent, 0.85, { transparent: true, opacity: 0.72, roughness: 0.1, metalness: 0.5 });
609:       for (let i = 0; i < 34; i++) {
610:         const side = i % 2 ? 1 : -1;
611:         const h = 2 + rng() * 16;
612:         const z = 8 + rng() * (length + 30);
613:         add(new THREE.ConeGeometry(0.8 + rng() * 2.5, h, 5), i % 3 ? shardMat : glass,
614:           side * (8.5 + rng() * 22), h / 2 - 1, z, 1, 1, 1, 0.02);
615:       }
616:       for (let i = 0; i < 18; i++) {
617:         add(new THREE.OctahedronGeometry(0.5 + rng() * 1.6), accent2, (rng() - 0.5) * 70, 4 + rng() * 25, 5 + rng() * length, 1, 1, 1, 0.5);
618:       }
619:     } else if (theme.motif === 'dunes') {
620:       for (let i = 0; i < 26; i++) {
621:         const side = i % 2 ? 1 : -1;
622:         const h = 2 + rng() * 9;
623:         const w = 5 + rng() * 12;
624:         add(new THREE.ConeGeometry(w, h, 3), dark, side * (15 + rng() * 30), h / 2 - 1.2, rng() * (length + 60), 1, 1, 1, 0);
625:         if (i % 3 === 0) add(new THREE.BoxGeometry(w * 0.9, 0.06, 0.08), accent, side * (15 + rng() * 30), h * 0.6, rng() * (length + 60), 1, 1, 1, 0);
626:       }
627:       for (let i = 0; i < 8; i++) {
628:         ring((i % 2 ? 30 : -30) + (rng() - .5) * 10, 12 + rng() * 16, 20 + rng() * length, 3 + rng() * 5, 0.07, accent2, 1.2, 0, 0, 0.1);
629:       }
630:     } else if (theme.motif === 'hex') {
631:       for (let i = 0; i < 24; i++) {
632:         const side = i % 2 ? 1 : -1;
633:         const h = 5 + rng() * 24;
634:         const r = 1.2 + rng() * 4.5;
635:         add(new THREE.CylinderGeometry(r, r, h, 6), i % 4 ? dark : glass,
636:           side * (11 + rng() * 24), h / 2 - 1.2, 8 + rng() * (length + 30), 1, 1, 1, 0.02);
637:         if (i % 3 === 0) add(new THREE.TorusGeometry(r * 0.85, 0.06, 5, 6), accent, side * (11 + rng() * 24), h * 0.7, 8 + rng() * length, 1, 1, 1, 0.15);
638:       }
639:       for (let i = 0; i < 16; i++) {
640:         add(new THREE.CylinderGeometry(1 + rng() * 2.8, 1 + rng() * 2.8, 0.15, 6), accent2,
641:           (rng() - 0.5) * 66, 5 + rng() * 24, 5 + rng() * length, 1, 1, 1, 0.2 + rng() * 0.3);
642:       }
643:     } else if (theme.motif === 'orbit') {
644:       for (let i = 0; i < 9; i++) {
645:         const side = i % 2 ? 1 : -1;
646:         const x = side * (20 + rng() * 26);
647:         const y = 9 + rng() * 21;
648:         const z = 12 + rng() * (length + 30);
649:         const r = 1.8 + rng() * 4.2;
650:         add(new THREE.IcosahedronGeometry(r, 1), i % 3 ? dark : accent, x, y, z, 1, 1, 1, 0.07);
651:         ring(x, y, z, r * 2.0, 0.06, i % 2 ? accent2 : accent, 0.9 + rng(), rng(), 0, 0.12);
652:         add(new THREE.SphereGeometry(r * 0.18, 10, 10), accent2, x + r * 1.9, y + r * 0.2, z, 1, 1, 1, 0.5);
653:       }
654:       for (let i = 0; i < 22; i++) {
655:         add(new THREE.OctahedronGeometry(0.25 + rng() * 0.7), accent, (rng() - 0.5) * 50, 2 + rng() * 30, rng() * length, 1, 1, 1, 0.4);
656:       }
657:     } else if (theme.motif === 'clocks') {
658:       for (let i = 0; i < 3; i++) {
659:         const side = i % 2 ? 1 : -1;
660:         const z = 30 + i * (length / 3);
661:         const x = side * 22;
662:         const y = 16;
663:         ring(x, y, z, 9, 0.13, accent, 0, Math.PI / 2, 0, 0.03);
664:         for (let t = 0; t < 12; t++) {
665:           const a = t / 12 * Math.PI * 2;
666:           const tick = add(new THREE.BoxGeometry(0.18, 1.1, 0.18), accent2,
667:             x + Math.cos(a) * 7.4, y + Math.sin(a) * 7.4, z, 1, 1, 1, 0);
668:           tick.rotation.z = a;
669:         }
670:       }
671:       for (let i = 0; i < 20; i++) {
672:         add(new THREE.BoxGeometry(0.8 + rng() * 2, 0.12, 0.8 + rng() * 2), glass, (rng() - 0.5) * 80, 4 + rng() * 22, rng() * length, 1, 1, 1, 0.02);
673:       }
674:     } else if (theme.motif === 'void') {
675:       for (let i = 0; i < 28; i++) {
676:         const side = i % 2 ? 1 : -1;
677:         const h = 6 + rng() * 32;
678:         const z = 8 + rng() * (length + 40);
679:         const x = side * (9 + rng() * 25);
680:         add(new THREE.BoxGeometry(1.2 + rng() * 4, h, 1.2 + rng() * 4), dark, x, h / 2 - 1.2, z, 1, 1, 1, 0.01);
681:         add(new THREE.BoxGeometry(0.09, h * 0.8, 0.09), accent, x + (rng() - .5) * 3, h * 0.5, z + 0.5, 1, 1, 1, 0);
682:       }
683:       ring(0, 24, length * 0.55, 30, 0.16, accent, 0, 0, 0, 0.02);
684:       for (let i = 0; i < 24; i++) {
685:         add(new THREE.BoxGeometry(1 + rng() * 2.2, 1 + rng() * 2.2, 0.3), accent2, (rng() - 0.5) * 82, 3 + rng() * 33, 5 + rng() * length, 1, 1, 1, 0.08 + rng() * 0.2);
686:       }
687:     } else {
688:       // clutter — intentionally ordered chaos
689:       const colors = [accent, accent2, glass, dark];
690:       for (let i = 0; i < 60; i++) {
691:         const geo = i % 3 === 0 ? new THREE.BoxGeometry(1 + rng() * 4, 1 + rng() * 4, 1 + rng() * 4) :
692:           i % 3 === 1 ? new THREE.TetrahedronGeometry(0.8 + rng() * 2.6) : new THREE.TorusGeometry(1 + rng() * 3, 0.12, 6, 18);
693:         add(geo, colors[i % 4], (rng() - 0.5) * 88, 3 + rng() * 34, 5 + rng() * length, 1, 1, 1, 0.1 + rng() * 0.35);
694:       }
695:     }
696: 
697:     // ambient dust cubes flanking every track
698:     for (let i = 0; i < 18; i++) {
699:       const side = i % 2 ? 1 : -1;
700:       add(new THREE.BoxGeometry(0.35, 0.35, 0.35), accent2, side * (6.4 + rng() * 6), 1 + rng() * 9, 10 + rng() * length, 1, 1, 1, 0.5);
701:     }
702:   }
