734:   /* ------------------------- obstacles ------------------------- */
735:   makeEventVisual(ev) {
736:     const theme = this.theme;
737:     const c = theme.colors;
738:     const group = new THREE.Group();
739:     const laneX = LANES[ev.lane] ?? 0;
740:     group.position.set(laneX, 0, ev.z);
741:     const edgeMat = this.material('edge', c.accent, c.accent, 1.5, { noCache: false });
742:     const edge2Mat = this.material('edge2', c.accent2, c.accent2, 1.7, { noCache: false });
743:     const darkMat = this.material('obstacleDark', '#070911', c.fog, 0.25, { metalness: 0.55, roughness: 0.36 });
744:     let obj = null;
745: 
746:     if (ev.type === 'spike') {
747:       const m = new THREE.Mesh(spikesGeo, this.material('spike', c.accent, c.accent, 1.1, { roughness: 0.28, metalness: 0.5 }));
748:       m.position.y = 0.725;
749:       group.add(m);
750:       const e = new THREE.LineSegments(edgesFor(spikesGeo), this.material('spikeEdge', c.text, c.text, 1.8, { noCache: true }));
751:       e.position.y = 0.725;
752:       group.add(e);
753:       const glow = new THREE.Sprite(new THREE.SpriteMaterial({ map: glowTexture(), color: c.accent, transparent: true, opacity: 0.45, blending: THREE.AdditiveBlending, depthWrite: false }));
754:       glow.scale.set(2.3, 2.3, 1); glow.position.y = 0.55;
755:       group.add(glow);
756:       this.materials.push(glow.material);
757:       obj = group;
758:     } else if (ev.type === 'block') {
759:       const m = new THREE.Mesh(blockGeo, darkMat);
760:       m.position.y = 0.85;
761:       group.add(m);
762:       const e = new THREE.LineSegments(edgesFor(blockGeo), edgeMat);
763:       e.position.y = 0.85;
