34:       this.sfxBus.connect(this.master);
35: 
36:       this.delay = this.ctx.createDelay(1.0);
37:       this.delay.delayTime.value = 0.22;
38:       const fb = this.ctx.createGain();
39:       fb.gain.value = 0.26;
40:       this.delay.connect(fb);
41:       fb.connect(this.delay);
42:       const wet = this.ctx.createGain();
43:       wet.gain.value = 0.34;
44:       this.delay.connect(wet);
45:       wet.connect(this.musicBus);
46: 
47:       // reusable noise buffer
48:       const len = this.ctx.sampleRate * 1;
49:       this.noise = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
50:       const data = this.noise.getChannelData(0);
51:       for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;
52:     }
53:     if (this.ctx.state === 'suspended') this.ctx.resume();
54:   }
55: 
56:   setMuted(muted) {
57:     this.muted = muted;
58:     if (this.master) this.master.gain.setTargetAtTime(muted ? 0 : 0.75, this.ctx.currentTime, 0.03);
59:     if (muted) this.stopMusic();
60:     else if (this.theme && this.musicOn) this.startMusic(this.theme);
61:   }
62: 
63:   startMusic(theme) {
64:     this.theme = theme;
65:     this.musicOn = true;
66:     if (this.muted) return;
67:     this.unlock();
68:     if (!this.ctx) return;
69:     this.stopScheduler();
70:     this.step = 0;
71:     this.nextTime = this.ctx.currentTime + 0.08;
72:     this.timer = setInterval(() => this.scheduler(), 28);
73:   }
74: 
75:   stopMusic() {
76:     this.musicOn = false;
77:     this.stopScheduler();
78:   }
79: 
80:   stopScheduler() {
81:     if (this.timer) clearInterval(this.timer);
82:     this.timer = null;
83:   }
84: 
85:   scheduler() {
86:     if (!this.ctx || this.muted || !this.theme) return;
87:     const bpm = this.theme.bpm || 150;
88:     const stepDur = 60 / bpm / 4;
89:     while (this.nextTime < this.ctx.currentTime + 0.13) {
90:       this.playStep(this.step, this.nextTime, stepDur);
91:       this.nextTime += stepDur;
92:       this.step = (this.step + 1) % 64;
93:     }
94:   }
95: 
96:   playStep(step, time, dur) {
97:     const theme = this.theme;
98:     const scale = theme.scale || [0, 2, 3, 7, 10];
99:     const root = theme.root || 45;
100:     const s = step % 16;
101:     const bar = Math.floor(step / 16) % 4;
102: 
103:     // Kick
104:     if (s % 4 === 0) this.kick(time);
105:     // Snare
106:     if (s === 4 || s === 12) this.snare(time);
107:     // Hats
108:     if (s % 2 === 0) this.hat(time, s % 4 === 2 ? 0.055 : 0.03);
109:     if (bar === 3 && s >= 12 && s % 2 === 1) this.hat(time, 0.022, true);
110: 
111:     // Bass
112:     if ([0, 3, 6, 8, 11, 14].includes(s)) {
113:       const degree = scale[(step + bar * 2) % scale.length];
114:       const octave = s < 8 ? 0 : -12;
115:       this.bass(time, root + degree + octave, dur * 1.4);
116:     }
117: 
118:     // Arpeggio
119:     if (s % 2 === 0 && bar !== 2) {
120:       const note = root + 12 + scale[(step * 3) % scale.length] + (bar === 3 ? 12 : 0);
121:       this.lead(time, note, dur * 0.72, 0.045);
122:     }
123: 
124:     // Chord stab
125:     if (s === 0) {
126:       [0, 4, 7].forEach((offset, i) => {
127:         this.pad(time, root + 12 + scale[0] + offset, dur * 14, 0.011 + i * 0.002);
128:       });
129:     }
130:   }
131: 
132:   kick(time) {
133:     const o = this.ctx.createOscillator();
134:     const g = this.ctx.createGain();
135:     o.type = 'sine';
136:     o.frequency.setValueAtTime(128, time);
137:     o.frequency.exponentialRampToValueAtTime(42, time + 0.12);
138:     g.gain.setValueAtTime(0.62, time);
139:     g.gain.exponentialRampToValueAtTime(0.001, time + 0.2);
140:     o.connect(g); g.connect(this.musicBus);
141:     o.start(time); o.stop(time + 0.22);
142:   }
143: 
144:   snare(time) {
145:     const src = this.ctx.createBufferSource();
146:     src.buffer = this.noise;
147:     const f = this.ctx.createBiquadFilter();
148:     f.type = 'highpass'; f.frequency.value = 1800;
149:     const g = this.ctx.createGain();
150:     g.gain.setValueAtTime(0.22, time);
151:     g.gain.exponentialRampToValueAtTime(0.001, time + 0.13);
152:     src.connect(f); f.connect(g); g.connect(this.musicBus);
153:     src.start(time); src.stop(time + 0.15);
154:   }
155: 
156:   hat(time, gain, open = false) {
157:     const src = this.ctx.createBufferSource();
158:     src.buffer = this.noise;
159:     const f = this.ctx.createBiquadFilter();
160:     f.type = 'highpass'; f.frequency.value = 7600;
161:     const g = this.ctx.createGain();
162:     g.gain.setValueAtTime(gain, time);
163:     g.gain.exponentialRampToValueAtTime(0.001, time + (open ? 0.08 : 0.035));
164:     src.connect(f); f.connect(g); g.connect(this.musicBus);
165:     src.start(time); src.stop(time + 0.1);
166:   }
167: 
168:   mtof(m) { return 440 * Math.pow(2, (m - 69) / 12); }
169: 
170:   bass(time, midi, len) {
171:     const o = this.ctx.createOscillator();
172:     const g = this.ctx.createGain();
173:     const f = this.ctx.createBiquadFilter();
174:     o.type = 'sawtooth';
175:     o.frequency.value = this.mtof(midi - 12);
176:     f.type = 'lowpass';
177:     f.frequency.setValueAtTime(480, time);
178:     f.Q.value = 7;
179:     g.gain.setValueAtTime(0.0001, time);
180:     g.gain.linearRampToValueAtTime(0.13, time + 0.015);
181:     g.gain.exponentialRampToValueAtTime(0.0001, time + len);
182:     o.connect(f); f.connect(g); g.connect(this.musicBus);
183:     o.start(time); o.stop(time + len + 0.02);
184:   }
185: 
186:   lead(time, midi, len, gain) {
187:     const o = this.ctx.createOscillator();
188:     const g = this.ctx.createGain();
189:     o.type = 'square';
190:     o.frequency.value = this.mtof(midi);
191:     g.gain.setValueAtTime(0.0001, time);
192:     g.gain.linearRampToValueAtTime(gain, time + 0.008);
193:     g.gain.exponentialRampToValueAtTime(0.0001, time + len);
194:     o.connect(g); g.connect(this.musicBus); g.connect(this.delay);
195:     o.start(time); o.stop(time + len + 0.02);
196:   }
197: 
198:   pad(time, midi, len, gain) {
199:     const o = this.ctx.createOscillator();
200:     const g = this.ctx.createGain();
201:     o.type = 'triangle';
202:     o.frequency.value = this.mtof(midi);
203:     g.gain.setValueAtTime(0.0001, time);
204:     g.gain.linearRampToValueAtTime(gain, time + 0.15);
205:     g.gain.exponentialRampToValueAtTime(0.0001, time + len);
206:     o.connect(g); g.connect(this.musicBus);
207:     o.start(time); o.stop(time + len + 0.02);
208:   }
209: 
210:   sfxJump() {
211:     if (!this.ctx || this.muted) return;
212:     const t = this.ctx.currentTime;
213:     const o = this.ctx.createOscillator();
214:     const g = this.ctx.createGain();
215:     o.type = 'triangle';
216:     o.frequency.setValueAtTime(520, t);
217:     o.frequency.exponentialRampToValueAtTime(980, t + 0.09);
218:     g.gain.setValueAtTime(0.13, t);
219:     g.gain.exponentialRampToValueAtTime(0.001, t + 0.11);
220:     o.connect(g); g.connect(this.sfxBus);
221:     o.start(t); o.stop(t + 0.12);
222:   }
223: 
224:   sfxCoin() {
225:     if (!this.ctx || this.muted) return;
226:     const t = this.ctx.currentTime;
227:     [880, 1320].forEach((f, i) => {
228:       const o = this.ctx.createOscillator();
229:       const g = this.ctx.createGain();
230:       o.type = 'sine'; o.frequency.value = f;
231:       g.gain.setValueAtTime(0.0001, t + i * 0.05);
232:       g.gain.linearRampToValueAtTime(0.11, t + i * 0.05 + 0.01);
233:       g.gain.exponentialRampToValueAtTime(0.0001, t + i * 0.05 + 0.16);
234:       o.connect(g); g.connect(this.sfxBus);
235:       o.start(t + i * 0.05); o.stop(t + i * 0.05 + 0.18);
236:     });
237:   }
238: 
239:   sfxDeath() {
240:     this.stopMusic();
241:     if (!this.ctx || this.muted) return;
242:     const t = this.ctx.currentTime;
243:     const o = this.ctx.createOscillator();
244:     const g = this.ctx.createGain();
245:     o.type = 'sawtooth';
246:     o.frequency.setValueAtTime(190, t);
247:     o.frequency.exponentialRampToValueAtTime(38, t + 0.55);
248:     g.gain.setValueAtTime(0.2, t);
249:     g.gain.exponentialRampToValueAtTime(0.001, t + 0.62);
250:     o.connect(g); g.connect(this.sfxBus);
251:     o.start(t); o.stop(t + 0.66);
252:   }
253: 
254:   sfxWin() {
255:     this.stopMusic();
256:     if (!this.ctx || this.muted) return;
257:     const t = this.ctx.currentTime;
258:     const notes = [0, 4, 7, 12, 16, 19, 24];
259:     notes.forEach((n, i) => {
260:       const o = this.ctx.createOscillator();
261:       const g = this.ctx.createGain();
262:       o.type = 'triangle';
263:       o.frequency.value = this.mtof(60 + n);
264:       const st = t + i * 0.085;
265:       g.gain.setValueAtTime(0.0001, st);
266:       g.gain.linearRampToValueAtTime(0.12, st + 0.012);
267:       g.gain.exponentialRampToValueAtTime(0.0001, st + 0.42);
268:       o.connect(g); g.connect(this.sfxBus);
269:       o.start(st); o.stop(st + 0.45);
270:     });
271:   }
272: }

