(() => {
  const W = window.__GD3D;
  if (!W || !W.world || !W.world.runtime) return "no game";
  if (window.__bot) clearInterval(window.__bot);
  const log = [];
  window.__botLog = log;
  let nextLaneAt = 0;
  let lastJumpAt = 0;
  const laneX = l => [2.75, 0, -2.75][l];

  function jumpSingle(now) {
    if (!W.world.player.grounded) return;
    W.world.jump();
    setTimeout(() => W.world.releaseJump(), 120);
    lastJumpAt = now;
    log.push({ t: Math.round(W.world.player.z * 10) / 10, a: "jump" });
    if (log.length > 120) log.shift();
  }

  function rowsAhead() {
    const w = W.world;
    const z = w.player.z;
    const rows = new Map();
    for (const e of w.eventObjects) {
      if (e.type === "coin") continue;
      if (e.z < z - 0.6 || e.z > z + 32) continue;
      const k = Math.round(e.z * 2) / 2;
      if (!rows.has(k)) rows.set(k, []);
      rows.get(k).push(e);
    }
    return [...rows.entries()].sort((a, b) => a[0] - b[0]);
  }

  window.__bot = setInterval(() => {
    const w = W.world;
    const p = w.player;
    if (W.state !== "playing" || !p.alive) return;
    const now = performance.now();
    const rows = rowsAhead();

    // choose lane: avoid gates hard, avoid hazards softly, and stand on pads
    let best = p.lane, bestScore = Infinity;
    for (let l = 0; l < 3; l++) {
      let score = Math.abs(l - p.lane) * 0.4;
      for (const [z, evs] of rows) {
        const d = z - p.z;
        if (d < -0.6 || d > 26) continue;
        if (evs.some(e => e.type === "gate" && e.lane === l)) score += d < 16 ? 900 : 90;
        if (evs.some(e => (e.type === "spike" || e.type === "block" || e.type === "saw") && e.lane === l)) score += d < 10 ? 34 : 5;
        if (evs.some(e => e.type === "hurdle")) score += d < 8 ? 18 : 2;
        const pad = evs.find(e => e.type === "pad");
        if (pad && pad.lane !== l) {
          const far = rows.find(([zz, ee]) => zz > z + 8 && zz < z + 20 && ee.filter(e => e.type === "spike").length >= 3);
          if (far) score += 800;
        }
        if (pad && pad.lane === l) score -= 10;
      }
      if (score < bestScore) { bestScore = score; best = l; }
    }
    if (best !== p.lane && now > nextLaneAt) {
      w.moveLane(Math.sign(best - p.lane));
      nextLaneAt = now + 70;
    }

    // jump timing
    let needJump = false;
    let padSoon = false;
    for (const [z, evs] of rows) {
      const d = z - p.z;
      if (d < -0.6 || d > 8) continue;
      if (evs.some(e => e.type === "pad" && e.lane === p.lane) && d < 7) padSoon = true;
      const jumpable = evs.some(e =>
        (e.type === "hurdle") ||
        ((e.type === "spike" || e.type === "block" || e.type === "saw") && e.lane === p.lane));
      if (jumpable && d < 4.6 && d > -0.4) needJump = true;
    }
    if (needJump && !padSoon && now - lastJumpAt > 260) jumpSingle(now);
  }, 16);

  return "bot started";
})()

