(() => {
  const W = window.__GD3D;
  if (!W || !W.levels) return "no levels hook";
  const results = [];
  const dt = 1 / 60;

  function laneSet(evs) {
    return [0, 1, 2].filter(l => !evs.some(e => e.type === "gate" && e.lane === l));
  }
  function openLane(evs, from) {
    const open = laneSet(evs);
    if (!open.length) return 1;
    return open.slice().sort((a, b) => Math.abs(a - from) - Math.abs(b - from))[0];
  }

  function step(w) {
    const p = w.player;
    const rows = [];
    const z = p.z;
    for (const e of w.eventObjects) {
      if (e.type === "coin" || e.z < z - 1 || e.z > z + 34) continue;
      const k = Math.round(e.z * 2) / 2;
      let row = rows.find(r => r.z === k);
      if (!row) { row = { z: k, evs: [] }; rows.push(row); }
      row.evs.push(e);
    }
    rows.sort((a, b) => a.z - b.z);

    const nextGate = rows.find(r => r.z > z + 0.4 && r.evs.some(e => e.type === "gate"));
    const nextPad = rows.find(r => r.z > z + 0.4 && r.evs.some(e => e.type === "pad"));
    let target = p.lane;
    if (nextGate && nextGate.z - z < 18) {
      target = openLane(nextGate.evs, p.lane);
      const later = rows.find(r => r.z > nextGate.z + 3 && r.z - z < 24 && r.evs.some(e => e.type === "gate"));
      if (later) {
        const both = laneSet(nextGate.evs).filter(l => laneSet(later.evs).includes(l));
        if (both.length) target = both.slice().sort((a, b) => Math.abs(a - p.lane) - Math.abs(b - p.lane))[0];
      }
    } else if (nextPad && nextPad.z - z < 22) {
      const pad = nextPad.evs.find(e => e.type === "pad");
      if (pad) target = pad.lane;
    }
    if (target !== p.lane) w.moveLane(Math.sign(target - p.lane));

    let needJump = false;
    let padSoon = false;
    for (const row of rows) {
      const d = row.z - z;
      if (d < -0.5 || d > 8.5) continue;
      if (row.evs.some(e => e.type === "pad" && e.lane === p.lane) && d < 7) padSoon = true;
      const jumpable = row.evs.some(e => e.type === "hurdle" ||
        (e.lane === p.lane && (e.type === "spike" || e.type === "block" || e.type === "saw")));
      if (jumpable && d < 4.4 && d > 0) needJump = true;
    }
    if (needJump && !padSoon && p.grounded) { w.jump(); w.releaseJump(); }
  }

  for (const level of W.levels) {
    W.startLevel(level);
    const w = W.world;
    let steps = 0;
    const maxSteps = Math.ceil((level.length / level.speed) / dt) + 300;
    while (!w.finished && !w.crashed && steps < maxSteps) {
      step(w);
      w.update(dt, steps * dt);
      steps++;
    }
    const nearby = w.eventObjects
      .filter(e => e.type !== "coin" && Math.abs(e.z - w.player.z) < 4)
      .map(e => ({ t: e.type, l: e.lane, z: e.z }));
    results.push({
      id: level.id,
      name: level.name,
      finished: w.finished,
      crashed: w.crashed,
      z: Math.round(w.player.z * 10) / 10,
      finishZ: w.runtime && w.runtime.finishZ,
      pct: Math.round(w.getProgress()),
      steps,
