(() => {
  const W = window.__GD3D;
  let out = "";
  for (const level of W.levels) {
    W.startLevel(level);
    const w = W.world;
    const rows = [];
    for (const e of w.eventObjects) {
      if (e.type === "coin") continue;
      const k = Math.round(e.z * 2) / 2;
      let row = rows.find(r => r.z === k);
      if (!row) { row = { z: k, evs: [] }; rows.push(row); }
      row.evs.push(e);
    }
    rows.sort((a, b) => a.z - b.z);
    const allJump = rows.filter(r => r.evs.some(e => e.type === "hurdle") || r.evs.filter(e => e.type === "spike").length >= 3);
    const v = level.speed, G = 37, J = 14.1;
    const t1 = (J - Math.sqrt(J * J - 2 * G * 1.37)) / G;
    const air = 2 * J / G, H = (2 * (J / G) - 2 * t1) * v;
    const L = air * v, minAfter = t1 * v;
    const bad = [];
    for (let i = 1; i < allJump.length; i++) {
      const D = allJump[i].z - allJump[i - 1].z;
      if (!(D <= H - 1.2) && !(D >= L + minAfter + 0.8)) {
        bad.push({ D: +D.toFixed(1), a: allJump[i - 1].z, b: allJump[i].z, at: allJump[i - 1].evs.map(e => e.type + ":" + e.lane), bt: allJump[i].evs.map(e => e.type + ":" + e.lane) });
      }
    }
    if (bad.length) out += level.name + " " + JSON.stringify(bad) + "\n";
  }
  return out || "no bad pairs";
})()
EOF
